#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ST7735.h>
// TFT display pins
#define TFT_CS   10
#define TFT_DC    9
#define TFT_RST   8
// Sensor and buzzer pins
#define LM35_PIN A1
#define BUZZER_PIN 7
Adafruit_ST7735 tft(TFT_CS, TFT_DC, TFT_RST);
// Temperature limits
const float MIN_TEMP = 20.0;
const float MAX_TEMP = 40.0;
void setup() {
Serial.begin(9600);
pinMode(BUZZER_PIN, OUTPUT);
digitalWrite(BUZZER_PIN, LOW);
// Initialize TFT
tft.initR(INITR_BLACKTAB);
// Correct display orientation
tft.setRotation(3);
tft.fillScreen(ST77XX_BLACK);
tft.setTextWrap(false);
}
void loop() {
// Read LM35 sensor
int reading = analogRead(LM35_PIN);

// Convert analog value to temperature
float voltage = reading * (5.0 / 1023.0);
float temperature = voltage * 100.0;
// Check temperature limits
bool alert = (temperature < MIN_TEMP ||
temperature > MAX_TEMP);
// Control buzzer
digitalWrite(BUZZER_PIN, alert ? HIGH : LOW);
// Clear display
tft.fillScreen(ST77XX_BLACK);
// Display title
tft.setTextSize(2);
tft.setTextColor(ST77XX_WHITE);
tft.setCursor(5, 10);
tft.println("LM35 Monitor");
// Display temperature
tft.setTextSize(3);
tft.setTextColor(ST77XX_CYAN);
tft.setCursor(5, 45);
tft.print(temperature, 1);
tft.print(" C");
// Display status
tft.setTextSize(2);
tft.setCursor(5, 90);
if (alert) {
tft.setTextColor(ST77XX_RED);
tft.println("ALERT!");
} else {
tft.setTextColor(ST77XX_GREEN);
tft.println("NORMAL");
}
// Print temperature in Serial Monitor
Serial.print("Temperature: ");
Serial.print(temperature, 1);
Serial.println(" C");
delay(1000);
}
