// HC-SR04 pins
const int trigPin = 9;
const int echoPin = 10;
// Buzzer pin
const int buzzerPin = 8;
long duration;
float distance;
void setup() {
pinMode(trigPin, OUTPUT);
pinMode(echoPin, INPUT);
pinMode(buzzerPin, OUTPUT);
lcd.init();
lcd.backlight();
lcd.setCursor(0, 0);
lcd.print("Ultrasonic Meter");
delay(1500);
lcd.clear();
