distance = duration * 0.0343 / 2.0;
lcd.clear();
lcd.setCursor(0, 0);
lcd.print("Distance:");
lcd.setCursor(0, 1);
lcd.print(distance, 1);
lcd.print(" cm");
Serial.print("Distance: ");
Serial.print(distance, 1);
Serial.println(" cm");
// Buzzer warning when object is closer than 10 cm
if (distance < 10) {
tone(buzzerPin, 2000);
} else {
noTone(buzzerPin);
}
}
delay(300);
}
