// Arduino UNO + LDR + HC-SR501 PIR + Relay
const int ldrPin = A0;
const int pirPin = 2;
const int relayPin = 8;
// Adjust this threshold according to your LDR readings
const int darknessThreshold = 400;
void setup() {
pinMode(ldrPin, INPUT);
pinMode(pirPin, INPUT);
pinMode(relayPin, OUTPUT);
// Many relay modules are active-LOW.
// This assumes an active-LOW relay.
digitalWrite(relayPin, HIGH);
Serial.begin(9600);
}
void loop() {
int lightValue = analogRead(ldrPin);
int motion = digitalRead(pirPin);

// With this setting, lower LDR readings mean darkness.
bool isDark = (lightValue < darknessThreshold);
bool motionDetected = (motion == HIGH);
Serial.print("Light value: ");
Serial.print(lightValue);
Serial.print(" | Motion: ");
Serial.print(motionDetected ? "Detected" : "Not detected");
if (isDark && motionDetected) {
digitalWrite(relayPin, LOW);  // Relay ON
Serial.println(" | Lamp ON");
} else {   digitalWrite(relayPin, HIGH); // Relay OFF
Serial.println(" | Lamp OFF");
}
delay(300);
}
