// LCD address: commonly 0x27
LiquidCrystal_I2C lcd(0x27, 16, 2);
// IR sensor pins
const int entrySensor = 2;
const int exitSensor  = 3;
int entryCount = 0;
int exitCount = 0;
int totalCount = 0;
bool lastEntryState = HIGH;
bool lastExitState  = HIGH;
void setup() {
pinMode(entrySensor, INPUT);
pinMode(exitSensor, INPUT);
lcd.init();
lcd.backlight();
lcd.setCursor(0, 0);
lcd.print("IR Object Counter");
delay(1500);
lcd.clear();
Serial.begin(9600);
}
void loop() {
bool entryState = digitalRead(entrySensor);
bool exitState  = digitalRead(exitSensor);

// Entry detection: Sensor 1 changes from HIGH to LOW
if (lastEntryState == HIGH && entryState == LOW) {
entryCount++;
totalCount++;
updateDisplay();
delay(200);
}
// Exit detection: Sensor 2 changes from HIGH to LOW
if (lastExitState == HIGH && exitState == LOW) {
exitCount++;
if (totalCount > 0) {
totalCount--;
}
updateDisplay();
delay(200);
}
lastEntryState = entryState;
lastExitState = exitState;
}
void updateDisplay() {
lcd.clear();
lcd.setCursor(0, 0);
lcd.print("Count: ");
lcd.print(totalCount);
lcd.setCursor(0, 1);
lcd.print("IN:");
lcd.print(entryCount);
lcd.print(" OUT:");
lcd.print(exitCount);
Serial.print("Total: ");
Serial.print(totalCount);
Serial.print(" | IN: ");
Serial.print(entryCount);
Serial.print(" | OUT: ");
Serial.println(exitCount);
}
