// START button
if (digitalRead(startButton) == HIGH &&
!timerRunning) {
timerRunning = true;
startTime = millis() - elapsedTime;
tone(buzzerPin, 1000, 100);
lcd.clear();
lcd.setCursor(0, 0);
lcd.print("Timer Started");
}
// Update timer
