elapsedTime = millis() - startTime;
displayTime();
}
// STOP button
if (digitalRead(stopButton) == HIGH &&
timerRunning) {
timerRunning = false;
tone(buzzerPin, 1500, 200);
lcd.clear();
lcd.setCursor(0, 0);
lcd.print("Timer Stopped");
displayTime();
delay(500);
}
// RESET button
if (digitalRead(resetButton) == HIGH) {
timerRunning = false;
elapsedTime = 0;
startTime = 0;
noTone(buzzerPin);
